    static SrppZeroTargetExitContext context(ObjectNode x)throws Exception{
        ObjectNode model=(ObjectNode)SrppReportFixtures.AUTHORITY.model().deepCopy();model.put("decision","D-236").put("policy_version","2.78.0");model.withObject("execution_policy").set("zero_target_high_zone_exit_d236",x.path("model").path("execution_policy").path("zero_target_high_zone_exit_d236"));
        boolean us=x.path("identity").path("market").asText().equals("US");String date=x.path("identity").path(us?"sessionDate":"tradingDate").asText();Instant at=Instant.parse(x.path("capturedAt").asText());String rawModel=model.toString();ObjectNode manifest=J.objectNode().put("schema_version",1).put("decision","D-236").put("policy_version","2.78.0").put("model_version","3.25.0");manifest.putObject("files").put("assumptions/model_inputs.json",SrppJcs.sha256Hex(rawModel));String hash=SrppJcs.hash(manifest);manifest.put("POLICY_BUNDLE_SHA256",hash);
        ObjectNode sources=x.withObject("sources");sources.set("policy",J.objectNode().put("bundleHash",hash).put("rawModelBytes",rawModel).put("rawManifestBytes",manifest.toString()).put("modelInputsSha256",SrppJcs.sha256Hex(rawModel)).put("policyManifestSha256",SrppJcs.sha256Hex(manifest.toString())));
        for(String key:List.of("zero-target-exit-state","report-reservations"))sources.withObject(key).put("policyBundleSha256",hash);
        sources=(ObjectNode)SrppReportModuleCalculator.normalize(sources);ObjectNode vector=J.objectNode();for(var e:sources.properties()){String digest=SrppJcs.hash(e.getValue());vector.putObject(e.getKey()).put("sourceId",e.getKey()).put("revision",digest).put("sha256",digest).put("capturedAt",at.toString()).put("coverage","COMPLETE").put("validation","VERIFIED");}
        return new SrppZeroTargetExitContext(model,sources,vector,7,LocalDate.parse(date),at,us?"美股":"台股",us?"22:45":"12:00",hash);
    }
